atts.custom_css:
selector{align-self:flex-start;width:auto;}
selector:hover { filter:var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow) !important; }
:where(selector){background-image:linear-gradient(to right, rgb(6, 182, 212), rgb(37, 99, 235));line-height:16px;transition:0.15s cubic-bezier(0.4, 0, 0.2, 1);}

selector{align-self:flex-start;width:auto;}
selector:hover { border-color:rgba(255, 255, 255, 0.3) !important; }
:where(selector){line-height:16px;transition:color 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), text-decoration-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), fill 0.15s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.15s cubic-bezier(0.4, 0, 0.2, 1), -webkit-text-decoration-color 0.15s cubic-bezier(0.4, 0, 0.2, 1);}
